// =====================================================================
//  VALIDACIÓN DEL DATASET (RN-14)
//  Cada registro se normaliza y valida ANTES de tocar la base de datos.
//  - Los inválidos se rechazan con su número de fila y el motivo exacto.
//  - Las suposiciones (p. ej. un estado vacío tomado como "disponible")
//    quedan registradas como advertencias: nada se corrige en silencio.
//  - Las reglas de negocio también aplican a los datos históricos:
//    aforo, cruces de horario, un préstamo activo por recurso, etc.
// =====================================================================
const MAX_REGISTROS = 5000;

// Nombres de columna aceptados por entidad, en orden de preferencia.
// Si el dataset oficial usa otro nombre, basta con agregarlo aquí.
const ALIAS = {
  espacios: {
    codigo: ['codigo', 'cod', 'code', 'codigo_espacio', 'id_espacio', 'espacio_id', 'id'],
    nombre: ['nombre', 'name', 'nombre_espacio', 'espacio'],
    tipo: ['tipo', 'type', 'tipo_espacio', 'categoria'],
    capacidad: ['capacidad', 'aforo', 'capacity', 'cupo', 'cupos', 'capacidad_maxima'],
    ubicacion: ['ubicacion', 'location', 'piso', 'bloque', 'sede', 'edificio'],
    equipamiento: ['equipamiento', 'equipos', 'dotacion', 'equipment', 'recursos'],
    estado: ['estado', 'status', 'state'],
  },
  recursos: {
    codigo: ['codigo', 'cod', 'code', 'placa', 'serial', 'codigo_recurso', 'id_recurso', 'recurso_id', 'id'],
    nombre: ['nombre', 'name', 'equipo', 'descripcion', 'recurso'],
    tipo: ['tipo', 'type', 'categoria', 'tipo_recurso'],
    espacio: ['espacio', 'espacio_codigo', 'codigo_espacio', 'espacio_id', 'id_espacio', 'ubicacion', 'aula'],
    estado: ['estado', 'status', 'state'],
  },
  reservas: {
    espacio: ['espacio', 'espacio_codigo', 'codigo_espacio', 'espacio_id', 'id_espacio', 'aula'],
    solicitante: ['solicitante', 'responsable', 'reservado_por', 'usuario', 'persona', 'nombre'],
    motivo: ['motivo', 'proposito', 'actividad', 'descripcion'],
    asistentes: ['asistentes', 'participantes', 'personas', 'cantidad', 'numero_asistentes'],
    fecha: ['fecha', 'date', 'dia', 'fecha_reserva'],
    hora_inicio: ['hora_inicio', 'inicio', 'desde', 'start', 'hora_desde'],
    hora_fin: ['hora_fin', 'fin', 'hasta', 'end', 'hora_hasta'],
    estado: ['estado', 'status'],
  },
  prestamos: {
    recurso: ['recurso', 'recurso_codigo', 'codigo_recurso', 'recurso_id', 'id_recurso', 'equipo', 'placa'],
    solicitante: ['solicitante', 'responsable', 'prestado_a', 'usuario', 'persona', 'nombre'],
    fecha_prestamo: ['fecha_prestamo', 'fecha_inicio', 'prestado_en', 'fecha_entrega', 'inicio', 'fecha'],
    fecha_limite: ['fecha_limite', 'fecha_devolucion_esperada', 'fecha_vencimiento', 'vence', 'limite', 'fecha_fin'],
    fecha_devolucion: ['fecha_devolucion', 'devuelto_en', 'fecha_devolucion_real', 'fecha_retorno'],
    estado: ['estado', 'status'],
    observaciones: ['observaciones', 'notas', 'comentarios'],
  },
  incidencias: {
    descripcion: ['descripcion', 'detalle', 'description', 'reporte', 'texto', 'asunto'],
    reportado_por: ['reportado_por', 'reportante', 'reporta', 'usuario', 'solicitante'],
    espacio: ['espacio', 'espacio_codigo', 'codigo_espacio', 'espacio_id', 'id_espacio', 'aula'],
    recurso: ['recurso', 'recurso_codigo', 'codigo_recurso', 'recurso_id', 'id_recurso', 'equipo'],
    categoria: ['categoria', 'category', 'tipo'],
    prioridad: ['prioridad', 'priority', 'urgencia'],
    area_responsable: ['area_responsable', 'area', 'responsable'],
    estado: ['estado', 'status'],
    fecha: ['fecha', 'fecha_reporte', 'creado_en', 'created_at'],
  },
};

// Valores aceptados por catálogo (escritos sin tildes y en minúsculas)
const ESTADOS = {
  espacios: {
    disponible: ['activo', 'activa', 'habilitado', 'habilitada', 'libre', 'operativo', 'operativa', 'available', 'ok'],
    mantenimiento: ['en mantenimiento', 'reparacion', 'en reparacion', 'maintenance'],
    inhabilitado: ['inhabilitada', 'deshabilitado', 'deshabilitada', 'fuera de servicio', 'cerrado', 'cerrada', 'inactivo', 'inactiva', 'disabled'],
  },
  recursos: {
    disponible: ['activo', 'habilitado', 'libre', 'operativo', 'funcional', 'available', 'ok', 'bueno'],
    mantenimiento: ['en mantenimiento', 'reparacion', 'en reparacion', 'danado', 'averiado', 'maintenance'],
    baja: ['dado de baja', 'retirado', 'obsoleto'],
    prestado: ['en prestamo', 'asignado', 'loaned'],
  },
  reservas: {
    activa: ['activo', 'confirmada', 'confirmado', 'aprobada', 'programada', 'vigente', 'reservada'],
    cancelada: ['cancelado', 'anulada', 'rechazada'],
    finalizada: ['finalizado', 'completada', 'cumplida', 'terminada'],
  },
  prestamos: {
    activo: ['activa', 'vigente', 'en curso', 'prestado', 'pendiente'],
    devuelto: ['devuelta', 'entregado', 'finalizado', 'cerrado', 'completado'],
  },
  incidencias: {
    abierta: ['abierto', 'nueva', 'pendiente', 'reportada', 'open'],
    en_proceso: ['en curso', 'en progreso', 'asignada', 'atendiendo'],
    resuelta: ['resuelto', 'solucionada', 'solucionado'],
    cerrada: ['cerrado', 'finalizada', 'closed'],
  },
};
const PRIORIDADES = {
  critica: ['critico', 'urgente', 'muy alta', 'emergencia'],
  alta: ['alto', 'high'],
  media: ['medio', 'normal', 'medium', 'moderada'],
  baja: ['bajo', 'low', 'menor'],
};

// ---------------------------------------------------------------------
//  Normalización
// ---------------------------------------------------------------------
const texto = (valor) => (valor === undefined || valor === null ? '' : String(valor).trim());
const sinTildes = (valor) => texto(valor).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const clave = (valor) => sinTildes(valor).replace(/[\s.-]+/g, '_');
const codigo = (valor) => texto(valor).toUpperCase().replace(/\s+/g, '-');
const entero = (valor) => (/^-?\d+(\.0+)?$/.test(texto(valor)) ? Number.parseInt(texto(valor), 10) : null);
const lista = (valor) => (Array.isArray(valor) ? valor : texto(valor).split(/[,;|]/)).map(sinTildes).filter(Boolean);
const minutos = (hora) => Number(hora.slice(0, 2)) * 60 + Number(hora.slice(3, 5));

function catalogo(valor, opciones) {
  const buscado = sinTildes(valor).replace(/_/g, ' ');
  for (const [canonico, sinonimos] of Object.entries(opciones)) {
    if (canonico.replace(/_/g, ' ') === buscado || sinonimos.includes(buscado)) return canonico;
  }
  return null;
}

// Fechas: AAAA-MM-DD, AAAA/MM/DD o DD/MM/AAAA
function fecha(valor) {
  const t = texto(valor);
  let partes = t.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (partes) partes = [partes[1], partes[2], partes[3]];
  else {
    const dma = t.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
    if (!dma) return null;
    partes = [dma[3], dma[2], dma[1]];
  }
  const iso = `${partes[0]}-${partes[1].padStart(2, '0')}-${partes[2].padStart(2, '0')}`;
  const comprobacion = new Date(`${iso}T00:00:00Z`);
  return !Number.isNaN(comprobacion.getTime()) && comprobacion.toISOString().slice(0, 10) === iso ? iso : null;
}

// Horas: 8:00, 08:00, 08:00:00, 8am, 2:30 p. m.
function hora(valor) {
  const t = sinTildes(valor).replace(/\s+/g, '').replace(/\./g, '');
  const partes = t.match(/^(\d{1,2})(?::(\d{2}))?(?::\d{2})?(am|pm)?$/);
  if (!partes) return null;
  let h = Number(partes[1]);
  const m = Number(partes[2] ?? 0);
  if (partes[3] === 'pm' && h < 12) h += 12;
  if (partes[3] === 'am' && h === 12) h = 0;
  if (h > 23 || m > 59) return null;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

// Fecha y hora: "2026-10-20 08:00", "2026-10-20T08:00:00", "20/10/2026 8:00 am"
function fechaHora(valor) {
  const [parteFecha, ...resto] = texto(valor).replace('T', ' ').split(/\s+/);
  const dia = fecha(parteFecha);
  if (!dia) return null;
  const h = resto.length ? hora(resto.join('').replace(/z$/i, '').replace(/[+-]\d{2}:?\d{2}$/, '')) : '00:00';
  return h ? `${dia}T${h}` : null;
}

function normalizarFila(fila, alias) {
  const porClave = {};
  for (const [nombre, valor] of Object.entries(fila)) porClave[clave(nombre)] = valor;
  const salida = {};
  for (const [campo, opciones] of Object.entries(alias)) {
    const columna = opciones.find((o) => porClave[o] !== undefined && texto(porClave[o]) !== '');
    salida[campo] = columna === undefined ? '' : porClave[columna];
  }
  return salida;
}

const respuestaError = (status, code, message) => [{ json: { ok: false, status, body: { ok: false, error: { code, message, details: [] } } } }];

// ---------------------------------------------------------------------
//  Entrada y datos existentes
// ---------------------------------------------------------------------
const ctx = $input.first().json;
const cuerpo = $('POST /importar').first().json.body ?? {};
const entidad = clave(cuerpo.entidad);
const registros = cuerpo.registros;
const archivo = texto(cuerpo.archivo).slice(0, 200) || null;

if (!ALIAS[entidad]) {
  return respuestaError(400, 'ENTIDAD_INVALIDA', `Entidad no soportada: "${texto(cuerpo.entidad)}". Usa: ${Object.keys(ALIAS).join(', ')}.`);
}
if (!Array.isArray(registros) || registros.length === 0) return respuestaError(400, 'SIN_REGISTROS', 'El archivo no contiene registros.');
if (registros.length > MAX_REGISTROS) {
  return respuestaError(413, 'DEMASIADOS_REGISTROS', `Se admiten máximo ${MAX_REGISTROS} registros por importación.`);
}

const espaciosPorCodigo = new Map(ctx.espacios.map((e) => [e.codigo, e]));
const recursosPorCodigo = new Map(ctx.recursos.map((r) => [r.codigo, r]));
const resolverEspacio = (valor) => espaciosPorCodigo.get(codigo(valor));
const resolverRecurso = (valor) => recursosPorCodigo.get(codigo(valor));
const enCatalogo = (valor, filas) => {
  const buscado = sinTildes(valor);
  return filas.find((f) => f.codigo === buscado.replace(/\s+/g, '_') || sinTildes(f.nombre) === buscado)?.codigo ?? null;
};

// Lo aceptado en este mismo archivo (duplicados, cruces y préstamos)
const aceptados = new Map();
const ocupacion = new Map();
const ocupar = (espacioId, dia, inicio, fin, origen) => {
  const llave = `${espacioId}|${dia}`;
  if (!ocupacion.has(llave)) ocupacion.set(llave, []);
  ocupacion.get(llave).push({ inicio, fin, origen });
};
ctx.reservas_activas.forEach((r) => ocupar(r.espacio_id, r.fecha, minutos(r.hora_inicio), minutos(r.hora_fin), 'ya registrada'));
const prestamosActivos = new Map(ctx.prestamos_activos.map((p) => [p.recurso_id, 'ya registrado']));

// ---------------------------------------------------------------------
//  Validadores por entidad: llenan "errores" (rechazo) y "avisos"
// ---------------------------------------------------------------------
const VALIDADORES = {
  espacios(r, errores, avisos) {
    const valor = {
      codigo: codigo(r.codigo),
      nombre: texto(r.nombre).slice(0, 120),
      tipo: sinTildes(r.tipo).slice(0, 40),
      capacidad: entero(r.capacidad),
      ubicacion: texto(r.ubicacion).slice(0, 120) || null,
      equipamiento: [...new Set(lista(r.equipamiento))],
      estado: 'disponible',
    };
    if (!valor.codigo) errores.push('falta el código');
    else if (valor.codigo.length > 40) errores.push('el código supera 40 caracteres');
    if (!valor.nombre) errores.push('falta el nombre');
    if (!valor.tipo) errores.push('falta el tipo');
    if (valor.capacidad === null) errores.push(`capacidad inválida ("${texto(r.capacidad)}")`);
    else if (valor.capacidad <= 0) errores.push(`la capacidad debe ser mayor que cero (${valor.capacidad})`);
    if (texto(r.estado)) {
      valor.estado = catalogo(r.estado, ESTADOS.espacios);
      if (!valor.estado) errores.push(`estado desconocido ("${texto(r.estado)}")`);
    } else {
      avisos.push('sin estado: se registró como "disponible"');
    }
    if (espaciosPorCodigo.has(valor.codigo)) errores.push(`el código ${valor.codigo} ya existe en la base de datos`);
    if (aceptados.has(valor.codigo)) errores.push(`código duplicado en el archivo (ya aparece en la fila ${aceptados.get(valor.codigo)})`);
    return { identificador: valor.codigo || valor.nombre, valor };
  },

  recursos(r, errores, avisos) {
    const espacio = texto(r.espacio) ? resolverEspacio(r.espacio) : null;
    const valor = {
      codigo: codigo(r.codigo),
      nombre: texto(r.nombre).slice(0, 120),
      tipo: sinTildes(r.tipo).slice(0, 40),
      espacio_id: espacio?.id ?? null,
      estado: 'disponible',
    };
    if (!valor.codigo) errores.push('falta el código');
    else if (valor.codigo.length > 40) errores.push('el código supera 40 caracteres');
    if (!valor.nombre) errores.push('falta el nombre');
    if (!valor.tipo) errores.push('falta el tipo');
    if (texto(r.espacio) && !espacio) errores.push(`el espacio "${texto(r.espacio)}" no existe (importa primero los espacios)`);
    if (texto(r.estado)) {
      const estado = catalogo(r.estado, ESTADOS.recursos);
      if (!estado) errores.push(`estado desconocido ("${texto(r.estado)}")`);
      else if (estado === 'prestado') {
        errores.push('no se importa como "prestado": el préstamo activo va en el archivo de préstamos, que actualiza el estado del recurso');
      } else valor.estado = estado;
    } else {
      avisos.push('sin estado: se registró como "disponible"');
    }
    if (recursosPorCodigo.has(valor.codigo)) errores.push(`el código ${valor.codigo} ya existe en la base de datos`);
    if (aceptados.has(valor.codigo)) errores.push(`código duplicado en el archivo (ya aparece en la fila ${aceptados.get(valor.codigo)})`);
    return { identificador: valor.codigo || valor.nombre, valor };
  },

  reservas(r, errores, avisos) {
    const espacio = texto(r.espacio) ? resolverEspacio(r.espacio) : null;
    const valor = {
      espacio_id: espacio?.id ?? null,
      solicitante: texto(r.solicitante).slice(0, 120),
      motivo: texto(r.motivo).slice(0, 200) || null,
      asistentes: entero(r.asistentes),
      fecha: fecha(r.fecha),
      hora_inicio: hora(r.hora_inicio),
      hora_fin: hora(r.hora_fin),
      estado: 'activa',
    };
    if (!texto(r.espacio)) errores.push('falta el espacio');
    else if (!espacio) errores.push(`el espacio "${texto(r.espacio)}" no existe`);
    if (!valor.solicitante) errores.push('falta el solicitante');
    if (valor.asistentes === null || valor.asistentes <= 0) errores.push(`número de asistentes inválido ("${texto(r.asistentes)}")`);
    if (!valor.fecha) errores.push(`fecha inválida ("${texto(r.fecha)}")`);
    if (!valor.hora_inicio) errores.push(`hora de inicio inválida ("${texto(r.hora_inicio)}")`);
    if (!valor.hora_fin) errores.push(`hora de fin inválida ("${texto(r.hora_fin)}")`);
    if (valor.hora_inicio && valor.hora_fin && minutos(valor.hora_fin) <= minutos(valor.hora_inicio)) {
      errores.push(`la hora de fin (${valor.hora_fin}) no es posterior a la de inicio (${valor.hora_inicio})`);
    }
    if (texto(r.estado)) {
      valor.estado = catalogo(r.estado, ESTADOS.reservas);
      if (!valor.estado) errores.push(`estado desconocido ("${texto(r.estado)}")`);
    }
    if (espacio && valor.asistentes > espacio.capacidad) {
      errores.push(`RN-02: ${valor.asistentes} asistentes superan la capacidad de ${espacio.codigo} (${espacio.capacidad})`);
    }
    if (!errores.length && valor.estado === 'activa') {
      const inicio = minutos(valor.hora_inicio);
      const fin = minutos(valor.hora_fin);
      const cruce = (ocupacion.get(`${valor.espacio_id}|${valor.fecha}`) ?? []).find((o) => inicio < o.fin && o.inicio < fin);
      if (cruce) errores.push(`RN-03: se cruza con otra reserva activa de ${espacio.codigo} (${cruce.origen})`);
    }
    const identificador = `${espacio?.codigo ?? texto(r.espacio)} ${valor.fecha ?? texto(r.fecha)} ${valor.hora_inicio ?? ''}`.trim();
    return { identificador, valor };
  },

  prestamos(r, errores, avisos) {
    const recurso = texto(r.recurso) ? resolverRecurso(r.recurso) : null;
    const valor = {
      recurso_id: recurso?.id ?? null,
      solicitante: texto(r.solicitante).slice(0, 120),
      fecha_prestamo: fechaHora(r.fecha_prestamo),
      fecha_limite: fechaHora(r.fecha_limite),
      fecha_devolucion: texto(r.fecha_devolucion) ? fechaHora(r.fecha_devolucion) : null,
      estado: null,
      observaciones: texto(r.observaciones).slice(0, 1000) || null,
    };
    if (!texto(r.recurso)) errores.push('falta el recurso');
    else if (!recurso) errores.push(`el recurso "${texto(r.recurso)}" no existe`);
    if (!valor.solicitante) errores.push('falta el solicitante');
    if (!valor.fecha_prestamo) errores.push(`fecha de préstamo inválida ("${texto(r.fecha_prestamo)}")`);
    if (!valor.fecha_limite) errores.push(`fecha límite inválida ("${texto(r.fecha_limite)}")`);
    if (texto(r.fecha_devolucion) && !valor.fecha_devolucion) errores.push(`fecha de devolución inválida ("${texto(r.fecha_devolucion)}")`);
    if (valor.fecha_prestamo && valor.fecha_limite && valor.fecha_limite <= valor.fecha_prestamo) {
      errores.push('la fecha límite no es posterior a la fecha del préstamo');
    }
    if (texto(r.estado)) {
      valor.estado = catalogo(r.estado, ESTADOS.prestamos);
      if (!valor.estado) errores.push(`estado desconocido ("${texto(r.estado)}")`);
    } else {
      valor.estado = valor.fecha_devolucion ? 'devuelto' : 'activo';
      avisos.push(`sin estado: se tomó como "${valor.estado}" según la fecha de devolución`);
    }
    if (valor.estado === 'devuelto') {
      if (!valor.fecha_devolucion) errores.push('un préstamo devuelto requiere la fecha de devolución');
      else if (valor.fecha_prestamo && valor.fecha_devolucion < valor.fecha_prestamo) errores.push('la devolución es anterior al préstamo');
    }
    if (valor.estado === 'activo') {
      if (valor.fecha_devolucion) errores.push('un préstamo activo no puede tener fecha de devolución');
      if (recurso && recurso.estado !== 'disponible' && !prestamosActivos.has(recurso.id)) {
        errores.push(`RN-05: el recurso ${recurso.codigo} está en "${recurso.estado}" y no puede tener un préstamo activo`);
      }
      if (recurso && prestamosActivos.has(recurso.id)) {
        errores.push(`el recurso ${recurso.codigo} ya tiene un préstamo activo (${prestamosActivos.get(recurso.id)})`);
      }
    }
    return { identificador: `${recurso?.codigo ?? texto(r.recurso)} → ${valor.solicitante || '?'}`, valor };
  },

  incidencias(r, errores, avisos) {
    const espacio = texto(r.espacio) ? resolverEspacio(r.espacio) : null;
    const recurso = texto(r.recurso) ? resolverRecurso(r.recurso) : null;
    const valor = {
      descripcion: texto(r.descripcion).slice(0, 2000),
      reportado_por: texto(r.reportado_por).slice(0, 120),
      espacio_id: espacio?.id ?? null,
      recurso_id: recurso?.id ?? null,
      categoria: null,
      prioridad: null,
      area_responsable: null,
      triaje: 'pendiente',
      estado: 'abierta',
      creado_en: null,
      resuelto_en: null,
    };
    if (valor.descripcion.length < 5) errores.push('falta la descripción');
    if (!valor.reportado_por) {
      valor.reportado_por = 'Dataset oficial';
      avisos.push('sin reportante: se registró como "Dataset oficial"');
    }
    if (texto(r.espacio) && !espacio) errores.push(`el espacio "${texto(r.espacio)}" no existe`);
    if (texto(r.recurso) && !recurso) errores.push(`el recurso "${texto(r.recurso)}" no existe`);
    if (texto(r.categoria)) {
      valor.categoria = enCatalogo(r.categoria, ctx.categorias);
      if (!valor.categoria) avisos.push(`la categoría "${texto(r.categoria)}" no está en el catálogo`);
    }
    if (texto(r.prioridad)) {
      valor.prioridad = catalogo(r.prioridad, PRIORIDADES);
      if (!valor.prioridad) avisos.push(`la prioridad "${texto(r.prioridad)}" no es válida`);
    }
    if (texto(r.area_responsable)) {
      valor.area_responsable = enCatalogo(r.area_responsable, ctx.areas);
      if (!valor.area_responsable) avisos.push(`el área "${texto(r.area_responsable)}" no está en el catálogo`);
    }
    if (valor.categoria && valor.prioridad && valor.area_responsable) valor.triaje = 'manual';
    else avisos.push('clasificación incompleta: queda pendiente de triaje (se puede clasificar con IA)');
    if (texto(r.estado)) {
      valor.estado = catalogo(r.estado, ESTADOS.incidencias);
      if (!valor.estado) errores.push(`estado desconocido ("${texto(r.estado)}")`);
    }
    if (texto(r.fecha)) {
      valor.creado_en = fechaHora(r.fecha);
      if (!valor.creado_en) errores.push(`fecha inválida ("${texto(r.fecha)}")`);
    }
    if (['resuelta', 'cerrada'].includes(valor.estado)) valor.resuelto_en = valor.creado_en ?? ctx.ahora.slice(0, 16);
    return { identificador: valor.descripcion.slice(0, 50), valor };
  },
};

// Registra lo aceptado para detectar duplicados y cruces dentro del archivo
const REGISTRAR_ACEPTADO = {
  espacios: (v, fila) => aceptados.set(v.codigo, fila),
  recursos: (v, fila) => aceptados.set(v.codigo, fila),
  reservas: (v, fila) => {
    if (v.estado === 'activa') ocupar(v.espacio_id, v.fecha, minutos(v.hora_inicio), minutos(v.hora_fin), `fila ${fila}`);
  },
  prestamos: (v, fila) => {
    if (v.estado === 'activo') prestamosActivos.set(v.recurso_id, `fila ${fila}`);
  },
  incidencias: () => {},
};

// ---------------------------------------------------------------------
//  Validación registro por registro
// ---------------------------------------------------------------------
const validos = [];
const rechazados = [];
const advertencias = [];

registros.forEach((original, indice) => {
  const fila = Number.isInteger(original?.__fila) ? original.__fila : indice + 1;
  if (!original || typeof original !== 'object' || Array.isArray(original)) {
    rechazados.push({ fila, identificador: '', errores: ['el registro no tiene el formato de un objeto'] });
    return;
  }
  const errores = [];
  const avisos = [];
  const { identificador, valor } = VALIDADORES[entidad](normalizarFila(original, ALIAS[entidad]), errores, avisos);
  if (errores.length) {
    rechazados.push({ fila, identificador, errores });
    return;
  }
  validos.push(valor);
  REGISTRAR_ACEPTADO[entidad](valor, fila);
  if (avisos.length) advertencias.push({ fila, identificador, mensajes: avisos });
});

return [{ json: { ok: true, entidad, archivo, total: registros.length, validos, rechazados, advertencias } }];

// =====================================================================
//  Resumen de la importación (evidencia de carga, validación y persistencia)
// =====================================================================
const validacion = $('Validar registros (RN-14)').first().json;
const NODOS_DE_INSERCION = ['Insertar espacios', 'Insertar recursos', 'Insertar reservas', 'Insertar préstamos', 'Insertar incidencias'];

let importacion = null;
for (const nodo of NODOS_DE_INSERCION) {
  try {
    importacion = $(nodo).first().json;
    if (importacion) break;
  } catch {
    // esa rama del Switch no se ejecutó
  }
}

const cambios = $input.all().flatMap(({ json }) => json.cambios ?? []);
const ETIQUETAS = { espacios: 'Espacios', recursos: 'Recursos', reservas: 'Reservas', prestamos: 'Préstamos', incidencias: 'Incidencias' };

const partes = [
  `${ETIQUETAS[validacion.entidad]}: ${importacion.insertados} de ${validacion.total} registro(s) cargado(s)`,
  `${validacion.rechazados.length} rechazado(s)`,
];
if (validacion.advertencias.length) partes.push(`${validacion.advertencias.length} con advertencias`);
if (cambios.length) partes.push(`${cambios.length} bloqueo(s) aplicado(s) por incidencias abiertas`);

return [
  {
    json: {
      status: 201,
      body: {
        ok: true,
        data: { importacion, rechazados: validacion.rechazados, advertencias: validacion.advertencias, cambios },
        message: `${partes.join(', ')}.`,
      },
    },
  },
];

