SELECT COALESCE(json_agg(i ORDER BY i.id DESC), '[]'::json) AS data
  FROM (SELECT id, entidad, archivo, total, insertados, rechazados, detalle, importado_en
          FROM importaciones ORDER BY id DESC LIMIT 50) i;

